param([string]$Raw='logs\inst_cli_raw_r5.txt',[string]$Markers='logs\inst_cli_markers_r5.csv',[string]$Map='logs\inst_cli_qpc_utc_map_r5.csv',[string]$Out='logs\inst_cli_analysis_r5.csv',[string]$Status='logs\inst_cli_analysis_r5.txt')
$ErrorActionPreference='Stop';$culture=[Globalization.CultureInfo]::InvariantCulture;$freq=[double][Diagnostics.Stopwatch]::Frequency
$mapRows=@(Import-Csv $Map);$xs=@();$ys=@();$br=@();foreach($r in $mapRows){$xs+=[double]$r.filetime_100ns;$ys+=([double]$r.qpc_pre+[double]$r.qpc_post)/2;$br+=1000*([double]$r.qpc_post-[double]$r.qpc_pre)/$freq}
$mx=($xs|Measure-Object -Average).Average;$my=($ys|Measure-Object -Average).Average;$num=0.0;$den=0.0;for($i=0;$i -lt $xs.Count;$i++){$num+=($xs[$i]-$mx)*($ys[$i]-$my);$den+=($xs[$i]-$mx)*($xs[$i]-$mx)};$slope=$num/$den;$intercept=$my-$slope*$mx
$res=@();for($i=0;$i -lt $xs.Count;$i++){$res+=([Math]::Abs($ys[$i]-($intercept+$slope*$xs[$i]))/$freq*1000)};$mapU=($res|Measure-Object -Maximum).Maximum+($br|Measure-Object -Maximum).Maximum/2+0.5
function StampQpc([string]$s){$dt=[DateTime]::ParseExact($s,'M/d/yyyy HH:mm:ss.fff',$culture,[Globalization.DateTimeStyles]::AssumeLocal);return $script:intercept+$script:slope*[double]$dt.ToFileTimeUtc()}
$chunks=[regex]::Split((Get-Content $Raw -Raw),'(?m)^==========\s*$');$rows=[Collections.Generic.List[object]]::new();foreach($c in $chunks){$stamp=([regex]::Match($c,'(?m)^\d{1,2}/\d{1,2}/\d{4}\s+\d{2}:\d{2}:\d{2}\.\d{3}\s*$')).Value.Trim();if(!$stamp){continue};$line=($c -split "`r?`n"|Where-Object {$_ -like 'INST_RETIRED.ANY*'}|Select-Object -First 1);if(!$line){continue};$f=$line -split "`t";$values=@();for($j=1;$j -lt $f.Count;$j++){$n=0L;if([long]::TryParse(($f[$j]-replace ',',''),[ref]$n)){$values+=$n}else{$values+=0L}};$rows.Add([pscustomobject]@{stamp=$stamp;end=(StampQpc $stamp);lp0=[long]$values[1]})}
$wins=[Collections.Generic.List[object]]::new();for($i=1;$i -lt $rows.Count;$i++){$a=[double]$rows[$i-1].end;$b=[double]$rows[$i].end;if($b -gt $a){$wins.Add([pscustomobject]@{index=$i;start=$a;end=$b;seconds=($b-$a)/$freq;count=[long]$rows[$i].lp0})}}
$marks=@(Import-Csv $Markers);$repResults=[Collections.Generic.List[object]]::new();$regions=@{};foreach($r in 1..5){$m0=$marks|Where-Object {$_.mark -eq 'REP_START' -and [int]$_.rep -eq $r}|Select-Object -First 1;$m1=$marks|Where-Object {$_.mark -eq 'REP_END' -and [int]$_.rep -eq $r}|Select-Object -First 1;$a=[double]$m0.qpc_start;$b=[double]$m1.qpc_end;$regions["REP$r"]=@{start=$a;end=$b;dur=($b-$a)/$freq};$repResults.Add([pscustomobject]@{rep=$r;start=$a;end=$b;duration=($b-$a)/$freq})};$m0=$marks|Where-Object mark -eq 'BASE_START'|Select-Object -First 1;$m1=$marks|Where-Object mark -eq 'BASE_END'|Select-Object -First 1;$ba=[double]$m0.qpc_start;$bb=[double]$m1.qpc_end;$regions.BASE=@{start=$ba;end=$bb;dur=($bb-$ba)/$freq}
$calc={param($reg) $sel=@($wins|Where-Object {$_.end -gt $reg.start -and $_.start -lt $reg.end});$full=@($sel|Where-Object {$_.start -ge $reg.start -and $_.end -le $reg.end});$sum=[long]0;$span=0.0;foreach($w in $sel){$sum+=$w.count;$span+=$w.seconds};$fcount=[long]0;$fspan=0.0;foreach($w in $full){$fcount+=$w.count;$fspan+=$w.seconds};return [pscustomobject]@{overlap=$sel.Count;contained=$full.Count;sum=$sum;span=$span;fullsum=$fcount;fullspan=$fspan}}
$base=&$calc $regions.BASE;$expected=60000000004L;$baseRate=[double]$base.sum/[double]$base.span;$outRows=[Collections.Generic.List[object]]::new();foreach($rep in $repResults){$r=&$calc @{start=$rep.start;end=$rep.end};$bg=$baseRate*$r.span;$bnet=[double]$r.sum-$bg;$bErr=100*($bnet-$expected)/$expected;$partialExpected=$expected*$r.fullspan/$rep.duration;$aErr=100*($r.fullsum-$partialExpected)/$partialExpected;$outRows.Add([pscustomobject]@{repetition=$rep.rep;N=20000000000;expected_exact=$expected;duration_s=$rep.duration;overlap_windows=$r.overlap;overlap_span_s=$r.span;overlap_LP0_count=$r.sum;BASE_rate_inst_s=$baseRate;BASE_subtracted_count=$bg;method_b_net_count=[Math]::Round($bnet);method_b_error_pct=$bErr;fully_contained_windows=$r.contained;contained_span_s=$r.fullspan;method_a_contained_count=$r.fullsum;method_a_expected_coverage_scaled=$partialExpected;method_a_error_pct=$aErr})};$outRows|Export-Csv -LiteralPath $Out -NoTypeInformation -Encoding utf8
$pass=@($outRows|Where-Object {[Math]::Abs($_.method_b_error_pct) -le 1}).Count -eq 5;$text=@("Method principal fijado antes de medir: (b), suma de todas las ventanas EMON que intersectan cada región QPC, menos el ritmo BASE LP0 por segundo multiplicado por el span EMON seleccionado; BASE es la región vacía del mismo LP/configuración y duración media R.","Diagnóstico (a): solo ventanas completamente contenidas; esperado exacto × span contenido/duración región. Supone ritmo de instrucciones constante; incertidumbre no acotada porque el bucle es una ráfaga/ritmo temporal no medido dentro de la ventana.","QPC frequency=$freq; QPC-UTC fit max residual ms=$(($res|Measure-Object -Maximum).Maximum); max bracket ms=$(($br|Measure-Object -Maximum).Maximum); header timestamp rounding=0.5ms; conservative U_ms=$mapU","Raw groups with timestamps=$($rows.Count); windows reconstructed=$($wins.Count); window duration median ms=$((1000*(@($wins|%{$_.seconds}|Sort-Object)[[int]($wins.Count/2)])))","BASE: duration_s=$($regions.BASE.dur); overlap_windows=$($base.overlap); overlap_span_s=$($base.span); LP0_INST_RETIRED_count=$($base.sum); LP0_background_rate_inst_s=$baseRate","R repetitions within ±1%=$((@($outRows|Where-Object {[Math]::Abs($_.method_b_error_pct) -le 1}).Count))/5; state=$(if($pass){'PASS'}else{'HOLD_INSTRUMENTATION'})","SMT sibling counts separately measured=NO");$text+=@($outRows|ForEach-Object {"REP$($_.repetition): duration_s=$($_.duration_s); overlap_windows=$($_.overlap_windows); contained=$($_.fully_contained_windows); coverage_pct=$([Math]::Round(100*$_.contained_span_s/$_.duration_s,4)); b_net=$($_.method_b_net_count); b_error_pct=$([Math]::Round($_.method_b_error_pct,6)); a_error_pct=$([Math]::Round($_.method_a_error_pct,6))"});$text|Set-Content -LiteralPath $Status -Encoding utf8;Get-Content $Status
